@Component("auditProgram-handler")
@ProcessingGroup("auditProgram-processing-group")
public class AuditProgramEventHandler {
	
	// core constructor
	AuditProgramEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAuditProgramEvent
     */
    @EventHandler
    public void handle( CreateAuditProgramEvent event) {
        entityManager.persist(new AuditProgram(event.getAuditProgramId(), event.getName(), event.getScope(), event.getOrganization(), event.getEngagements(), event.getCycle(), event.getStatus()));
    }

    /*
     * @param	event UpdateAuditProgramEvent
     */
    @EventHandler
    public AuditProgram handle( UpdateAuditProgramEvent event) {
    	entityManager.merge(new AuditProgram(event.getAuditProgramId(), event.getName(), event.getScope(), event.getOrganization(), event.getEngagements(), event.getCycle(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteAuditProgramEvent
     */
    @EventHandler
    public void on( DeleteAuditProgramEvent event) {
    	AuditProgram entity = new AuditProgram();
   
    	// ------------------------------------------
    	// apply the AuditProgramId
    	// ------------------------------------------
    	entity.setAuditProgramId( event.getAuditProgramId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AuditProgramRepository auditProgramEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AuditProgramEventHandler.class.getName());

}
